STEP 1 — Modify frontend/src/index.css. The Tailwind v4 @theme block defines the dark palette as the default (--color-canvas: #07090e etc.). We keep it as-is (dark is the default). Add a [data-theme='light'] selector block AFTER the @layer base block (not inside @theme) that overrides only the surface/text/border tokens with a white/gray light palette. Do NOT redefine semantic colors (pass, fail, warn, info and their -dim variants) — they work fine in both themes. Also add a transition rule to html for smooth theme switching, and update the .md-body strong rule so it is not hardcoded to text-white. Exact CSS to add:

/* Theme transition */
html {
  transition: background-color 0.25s ease, color 0.25s ease;
}

/* Light theme overrides — applied when <html data-theme='light'> */
[data-theme='light'] {
  --color-canvas: #f8f9fc;
  --color-sunken: #f0f2f7;
  --color-surface: #ffffff;
  --color-raised: #f4f6fb;
  --color-elevated: #eef1f8;
  --color-line: #d8dde8;
  --color-line-soft: #e4e8f2;
  --color-ink: #0f1623;
  --color-muted: #4a5568;
  --color-faint: #8896aa;
}

Also in .md-body strong, change `@apply font-semibold text-white;` to `@apply font-semibold text-ink;` so it respects the theme.

Also update the ambient blobs in Layout.tsx (they use inline style radial-gradient with rgba values that are fine in both themes — no change needed there).

Also update scrollbar colors: add [data-theme='light'] * { scrollbar-color: #c8cfe0 transparent; } and corresponding webkit rules.

Also update color-scheme: in @layer base html block, change `color-scheme: dark;` to `color-scheme: dark light;` so the browser adapts native inputs in light mode.

STEP 2 — Create frontend/src/context/ThemeContext.tsx (create the context/ directory). Implement:

export type Theme = 'dark' | 'light';

const STORAGE_KEY = 'lf-theme';

function getInitialTheme(): Theme {
  const stored = localStorage.getItem(STORAGE_KEY) as Theme | null;
  if (stored === 'dark' || stored === 'light') return stored;
  // Fall back to system preference
  return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
}

function applyTheme(theme: Theme) {
  const root = document.documentElement;
  if (theme === 'light') {
    root.setAttribute('data-theme', 'light');
  } else {
    root.removeAttribute('data-theme'); // dark is the default
  }
  // Keep color-scheme in sync for native UI elements
  root.style.colorScheme = theme;
}

interface ThemeContextValue {
  theme: Theme;
  toggleTheme: () => void;
}

const ThemeContext = createContext<ThemeContextValue | null>(null);

export function ThemeProvider({ children }: { children: ReactNode }) {
  const [theme, setTheme] = useState<Theme>(getInitialTheme);

  useEffect(() => {
    applyTheme(theme);
    localStorage.setItem(STORAGE_KEY, theme);
  }, [theme]);

  const toggleTheme = useCallback(() => {
    setTheme((t) => (t === 'dark' ? 'light' : 'dark'));
  }, []);

  return (
    <ThemeContext.Provider value={{ theme, toggleTheme }}>
      {children}
    </ThemeContext.Provider>
  );
}

export function useTheme(): ThemeContextValue {
  const ctx = useContext(ThemeContext);
  if (!ctx) throw new Error('useTheme must be used inside ThemeProvider');
  return ctx;
}

Imports needed: createContext, useCallback, useContext, useEffect, useState from 'react'; ReactNode from 'react'.

STEP 3 — Create frontend/src/components/ThemeToggle.tsx. Implement a button using the Sun and Moon icons from lucide-react (both are in lucide-react >=0.263). Use useTheme() to get theme and toggleTheme. Render Sun icon when theme is 'dark' (clicking goes to light) and Moon icon when theme is 'light' (clicking goes to dark). Style using existing .icon-btn class. Add aria-label that reflects current action. Example:

import { Moon, Sun } from 'lucide-react';
import { useTheme } from '../context/ThemeContext';

export function ThemeToggle({ className }: { className?: string }) {
  const { theme, toggleTheme } = useTheme();
  return (
    <button
      type='button'
      onClick={toggleTheme}
      className={clsx('icon-btn border border-line bg-raised', className)}
      aria-label={theme === 'dark' ? 'Switch to light mode' : 'Switch to dark mode'}
      title={theme === 'dark' ? 'Light mode' : 'Dark mode'}
    >
      {theme === 'dark' ? (
        <Sun className='h-4 w-4' aria-hidden='true' />
      ) : (
        <Moon className='h-4 w-4' aria-hidden='true' />
      )}
    </button>
  );
}
